function DataFooter({shown,total}:{shown:number;total:number}){return <div className="data-footer"><span>Showing 1 to {shown} of {total} entries</span><nav><button aria-label="Previous page"><ChevronLeftIcon/></button><button className="active">1</button><button>2</button><button>3</button><button aria-label="Next page"><ChevronRight/></button></nav></div>}
