function DataTableOne(){const [entries,setEntries]=useState(10);const [search,setSearch]=useState("");const [sort,setSort]=useState(0);const rows=[...staffRows].filter(row=>row.join(" ").toLowerCase().includes(search.toLowerCase())).sort((a,b)=>String(a[sort]).localeCompare(String(b[sort]))).slice(0,entries);return <TableCard title="Data Table 1"><DataControls entries={entries} setEntries={setEntries} search={search} setSearch={setSearch}/><table className="data-table"><thead><tr>{["User","Position","Office","Age","Start Date","Salary"].map((label,index)=><SortHead onClick={()=>setSort(index)} key={label}>{label}</SortHead>)}</tr></thead><tbody>{rows.map(([name,position,office,age,date,salary,user])=><tr key={name}><td><div className="basic-person"><img src={asset(`/images/user/user-${user}.jpg`)} alt="user"/><b>{name}</b></div></td><td>{position}</td><td>{office}</td><td>{age}</td><td>{date}</td><td>{salary}</td></tr>)}</tbody></table><DataFooter shown={rows.length} total={staffRows.length}/></TableCard>}
function DataTableTwo(){const [entries,setEntries]=useState(10);const [search,setSearch]=useState("");const [sort,setSort]=useState(0);const rows=[...staffRows].filter(row=>row.join(" ").toLowerCase().includes(search.toLowerCase())).sort((a,b)=>String(a[sort]).localeCompare(String(b[sort]))).slice(0,entries);return <TableCard title="Data Table 2"><DataControls entries={entries} setEntries={setEntries} search={search} setSearch={setSearch}/><table className="data-table"><thead><tr>{["User","Position","Office","Age","Start Date","Salary"].map((label,index)=><SortHead onClick={()=>setSort(index)} key={label}>{label}</SortHead>)}<th>Action</th></tr></thead><tbody>{rows.map(([name,position,office,age,date,salary])=><tr key={name}><td><b>{name}</b></td><td>{position}</td><td>{office}</td><td>{age}</td><td>{date}</td><td>{salary}</td><td><div className="basic-actions"><button aria-label="Edit"><Pencil/></button><button aria-label="Delete"><Trash2/></button></div></td></tr>)}</tbody></table><DataFooter shown={rows.length} total={staffRows.length}/></TableCard>}
function DataTableThree(){const [entries,setEntries]=useState(5);const [search,setSearch]=useState("");const rows=applicantRows.filter(row=>row.join(" ").toLowerCase().includes(search.toLowerCase())).slice(0,entries);return <TableCard title="Data Table 3"><DataControls entries={entries} setEntries={setEntries} search={search} setSearch={setSearch}/><table className="data-table"><thead><tr>{["User","Position","Salary","Office","Status"].map(label=><SortHead onClick={()=>{}} key={label}>{label}</SortHead>)}<th>Action</th></tr></thead><tbody>{rows.map(([name,position,salary,office,status])=><tr key={name}><td><div className="basic-person"><i>{name.split(" ").map(word=>word[0]).join("")}</i><span><b>{name}</b><small>demoemail@gmail.com</small></span></div></td><td>{position}</td><td>{salary}</td><td>{office}</td><td><Status>{status}</Status></td><td><div className="basic-actions"><button aria-label="Edit"><Pencil/></button><button aria-label="Delete"><Trash2/></button></div></td></tr>)}</tbody></table><DataFooter shown={rows.length} total={applicantRows.length}/></TableCard>}

const alertGroups=[
 {title:"Success Alert",tone:"success",message:"Success Message",icon:CircleCheck},
 {title:"Warning Alert",tone:"warning",message:"Warning Message",icon:Info},
 {title:"Error Alert",tone:"error",message:"Error Message",icon:AlertCircle},
 {title:"Info Alert",tone:"info",message:"Info Message",icon:Info}
] as const;
function AlertsPage(){return <><Head title="Alerts"/><div className="alerts-reference-page">{alertGroups.map(group=><AlertSection key={group.title} {...group}/>)}</div></>}
function AlertSection({title,tone,message,icon:Icon}:{title:string;tone:string;message:string;icon:React.ComponentType<{className?:string}>}){return <section className="alert-reference-card"><header><h2>{title}</h2></header><div>{[true,false].map((linked,index)=><div className={`premium-alert ${tone}`} key={index}><Icon className="premium-alert-icon"/><div><h3>{message}</h3><p>Be cautious when performing this action.</p>{linked?<a href="#" onClick={event=>event.preventDefault()}>Learn more</a>:null}</div></div>)}</div></section>}

const cardText="Lorem ipsum dolor sit amet, consectetur adipisicing elit. Animi architecto aspernatur cum et ipsum";
function CardsPage(){return <><Head title="Cards"/><div className="cards-reference-page">
 <CardShowcase title="Card with Image"><div className="cards-image-grid"><ReferenceImageCard image={1} title button/><ReferenceImageCard image={2} button/><ReferenceImageCard image={3} title link/></div></CardShowcase>
 <CardShowcase title="Horizontal Card with Image"><div className="cards-horizontal-grid"><ReferenceHorizontalCard image={1} button/><ReferenceHorizontalCard image={3} link/></div></CardShowcase>
 <CardShowcase title="Card with link"><div className="cards-link-grid"><ReferenceTextCard button/><ReferenceTextCard link/></div></CardShowcase>
 <CardShowcase title="Card with Icon"><div className="cards-icon-grid"><ReferenceIconCard/><ReferenceIconCard link/></div></CardShowcase>
 </div></>}
function CardShowcase({title,children}:{title:string;children:React.ReactNode}){return <section className="card-showcase"><header><h2>{title}</h2></header><div>{children}</div></section>}
function CardBody({title=true,button=false,link=false}:{title?:boolean;button?:boolean;link?:boolean}){return <div className="reference-card-body">{title?<h3>Card title</h3>:null}<p>{cardText}</p>{button?<a className="reference-card-button" href="#" onClick={event=>event.preventDefault()}>Read more</a>:null}{link?<a className="reference-card-link" href="#" onClick={event=>event.preventDefault()}><Link2/>Card link</a>:null}</div>}
function ReferenceImageCard({image,title=false,button=false,link=false}:{image:number;title?:boolean;button?:boolean;link?:boolean}){return <article className="reference-image-card"><img src={asset(`/images/cards/card-0${image}.png`)} alt="card"/><CardBody title={title} button={button} link={link}/></article>}
function ReferenceHorizontalCard({image,button=false,link=false}:{image:number;button?:boolean;link?:boolean}){return <article className="reference-horizontal-card"><img src={asset(`/images/cards/card-0${image}.png`)} alt="card"/><CardBody button={button} link={link}/></article>}
function ReferenceTextCard({button=false,link=false}:{button?:boolean;link?:boolean}){return <article className="reference-text-card"><CardBody button={button} link={link}/></article>}
function ReferenceIconCard({link=false}:{link?:boolean}){return <article className="reference-icon-card"><span><Box/></span><h3>Card title</h3><p>{cardText}</p>{link?<a href="#" onClick={event=>event.preventDefault()}>Read more <ArrowRight/></a>:null}</article>}

const carouselImages=[1,2,3,4].map(index=>asset(`/images/carousel/carousel-0${index}.png`));
function CarouselPage(){return <><Head title="Carousel"/><main className="carousel-reference-page">
 <CarouselCard title="Slides Only"><PremiumCarousel/></CarouselCard>
 <CarouselCard title="With controls"><PremiumCarousel controls/></CarouselCard>
 <CarouselCard title="With indicators"><PremiumCarousel indicators/></CarouselCard>
 <CarouselCard title="With controls and indicators"><PremiumCarousel controls indicators compactControls/></CarouselCard>
 </main></>}
function CarouselCard({title,children}:{title:string;children:React.ReactNode}){return <section className="carousel-card"><header><h2>{title}</h2></header><div className="carousel-card-body">{children}</div></section>}
function PremiumCarousel({controls=false,indicators=false,compactControls=false}:{controls?:boolean;indicators?:boolean;compactControls?:boolean}){
 const [active,setActive]=useState(0);
 useEffect(()=>{const timer=window.setInterval(()=>setActive(value=>(value+1)%carouselImages.length),4500);return()=>window.clearInterval(timer)},[]);
 const move=(amount:number)=>setActive(value=>(value+amount+carouselImages.length)%carouselImages.length);
 return <div className={`premium-carousel ${compactControls?"compact-controls":""}`}>
  <div className="carousel-track" style={{transform:`translate3d(-${active*100}%,0,0)`}}>{carouselImages.map((src,index)=><div className="carousel-slide" key={src} aria-hidden={index!==active}><img src={src} alt={`Carousel slide ${index+1}`}/></div>)}</div>
  {controls?<><button className="carousel-arrow prev" onClick={()=>move(-1)} aria-label="Previous slide"><ArrowLeft/></button><button className="carousel-arrow next" onClick={()=>move(1)} aria-label="Next slide"><ArrowRight/></button></>:null}
  {indicators?<div className="carousel-indicators" aria-label="Choose slide">{carouselImages.map((_,index)=><button key={index} className={index===active?"active":""} onClick={()=>setActive(index)} aria-label={`Go to slide ${index+1}`}/>)}</div>:null}
 </div>
}

type DropdownItem={label:string;icon?:React.ReactNode;dividerBefore?:boolean};
const defaultDropdownItems:DropdownItem[]=[{label:"Edit Profile"},{label:"Account Settings"},{label:"License"},{label:"Support"}];
const dividerDropdownItems:DropdownItem[]=[{label:"Edit"},{label:"Duplicate"},{label:"Archive",dividerBefore:true},{label:"Move"},{label:"Delete",dividerBefore:true}];
const iconDropdownItems:DropdownItem[]=[{label:"Edit profile",icon:<User/>},{label:"Settings",icon:<SlidersHorizontal/>},{label:"Support",icon:<Info/>},{label:"Sign out",icon:<ArrowRight/> ,dividerBefore:true}];
const iconDividerItems:DropdownItem[]=[{label:"Edit profile",icon:<User/>},{label:"Settings",icon:<SlidersHorizontal/>},{label:"Team",icon:<Layers3/>,dividerBefore:true},{label:"Subscription",icon:<RectangleVertical/>},{label:"Sign out",icon:<ArrowRight/>,dividerBefore:true}];
function DropdownsPage(){return <><Head title="Dropdowns"/><main className="dropdown-reference-page">
 <DropdownCard title="Default Dropdown"><PremiumDropdown label="Account Menu" items={defaultDropdownItems}/></DropdownCard>
 <DropdownCard title="Dropdown With Divider"><PremiumDropdown label="Options" items={dividerDropdownItems}/></DropdownCard>
 <DropdownCard title="Dropdown With Icon"><PremiumDropdown label="Account Menu" items={iconDropdownItems}/></DropdownCard>
 <DropdownCard title="Dropdown With Icon and Divider"><PremiumDropdown label="Account Menu" items={iconDividerItems}/></DropdownCard>
 </main></>}
function DropdownCard({title,children}:{title:string;children:React.ReactNode}){return <section className="dropdown-card"><header><h2>{title}</h2></header><div className="dropdown-card-body">{children}</div></section>}
function PremiumDropdown({label,items}:{label:string;items:DropdownItem[]}){const [open,setOpen]=useState(false);return <div className="premium-dropdown"><button className="dropdown-trigger" onClick={()=>setOpen(value=>!value)} aria-haspopup="menu" aria-expanded={open}>{label}<ChevronDown className={open?"open":""}/></button>{open?<div className="dropdown-menu" role="menu">{items.map(item=><div key={item.label}>{item.dividerBefore?<span className="dropdown-divider"/>:null}<button role="menuitem">{item.icon}<span>{item.label}</span></button></div>)}</div>:null}</div>}

function PaginationPage(){return <><Head title="Pagination"/><main className="pagination-reference-page">
 <PaginationCard title="Pagination with Text"><PremiumPagination variant="text"/></PaginationCard>
 <PaginationCard title="Pagination with Text and Icon"><PremiumPagination variant="text-icon"/></PaginationCard>
 <PaginationCard title="Pagination with  Icon"><PremiumPagination variant="icon"/></PaginationCard>
 </main></>}
function PaginationCard({title,children}:{title:string;children:React.ReactNode}){return <section className="pagination-card"><header><h2>{title}</h2></header><div className="pagination-card-body">{children}</div></section>}
function PremiumPagination({variant}:{variant:"text"|"text-icon"|"icon"}){const [page,setPage]=useState(1);const pages=[1,2,3,4,5,"…",10] as const;const previous=()=>setPage(value=>Math.max(1,value-1));const next=()=>setPage(value=>Math.min(10,value+1));const showIcons=variant!=="text";const iconOnly=variant==="icon";return <nav className={`premium-pagination ${iconOnly?"icon-only-pagination":""}`} aria-label="Pagination">
 <button className="pagination-nav previous" onClick={previous} disabled={page===1} aria-label="Previous page"><ArrowLeft className={showIcons?"":"mobile-only-arrow"}/>{iconOnly?null:<span>Previous</span>}</button>
 <span className="pagination-mobile-status">Page {page} of 10</span>
 <div className="pagination-pages">{pages.map((item,index)=>item==="…"?<span className="pagination-ellipsis" key={`dots-${index}`}>...</span>:<button key={item} className={page===item?"active":""} onClick={()=>setPage(item)} aria-current={page===item?"page":undefined}>{item}</button>)}</div>
 <button className="pagination-nav next" onClick={next} disabled={page===10} aria-label="Next page">{iconOnly?null:<span>Next</span>}<ArrowRight className={showIcons?"":"mobile-only-arrow"}/></button>
 </nav>}

type PopoverDirection="top"|"bottom"|"right"|"left";
type PopoverVariant="default"|"buttons"|"link";
const popoverDirections:PopoverDirection[]=["top","bottom","right","left"];
function PopoversPage(){return <><Head title="Popovers"/><main className="popovers-reference-page">
 <PopoverCard title="Default Popover"><PopoverRow variant="default"/></PopoverCard>
 <PopoverCard title="Popover With Button"><PopoverRow variant="buttons"/></PopoverCard>
 <PopoverCard title="Popover With Link"><PopoverRow variant="link"/></PopoverCard>
 </main></>}
function PopoverCard({title,children}:{title:string;children:React.ReactNode}){return <section className="popover-card"><header><h2>{title}</h2></header><div className="popover-card-body"><div className="popover-scroll">{children}</div></div></section>}
function PopoverRow({variant}:{variant:PopoverVariant}){const [open,setOpen]=useState<PopoverDirection|null>(null);return <div className="popover-row">{popoverDirections.map(direction=><div className="popover-anchor" key={direction}><button className="popover-trigger" onClick={()=>setOpen(value=>value===direction?null:direction)} aria-expanded={open===direction} aria-haspopup="dialog">Popover on {direction[0].toUpperCase()+direction.slice(1)}</button>{open===direction?<PopoverPanel direction={direction} variant={variant}/>:null}</div>)}</div>}
function PopoverPanel({direction,variant}:{direction:PopoverDirection;variant:PopoverVariant}){return <div className={`popover-panel ${direction}`} role="dialog"><header><h3>{direction[0].toUpperCase()+direction.slice(1)} Popover</h3></header><div className="popover-content"><p>Lorem ipsum dolor sit amet, consect adipiscing elit. Mauris facilisis congue exclamate justo nec facilisis.</p>{variant==="buttons"?<div className="popover-actions"><button>Yes! got it</button><button>Learn more</button></div>:null}{variant==="link"?<a href="#" onClick={event=>event.preventDefault()}>Learn More <ArrowRight/></a>:null}</div><span className="popover-pointer"/></div>}

type TabVariant="default"|"underline"|"icon"|"badge"|"vertical";
const tabLabels=["Overview","Notification","Analytics","Customers"] as const;
const tabIcons=[<Layers3 key="overview"/>,<Bell key="notification"/>,<ArrowUpDown key="analytics"/>,<User key="customers"/>];
const tabBadges:Record<string,string>={Overview:"8",Analytics:"4",Customers:"12"};
function TabsPage(){return <main className="tabs-reference-page">
 <TabsCard title="Default Tab" variant="default"/>
 <TabsCard title="Tab With Underline" variant="underline"/>
 <TabsCard title="Tab with line and icon" variant="icon"/>
 <TabsCard title="Tab with badge" variant="badge"/>
 <TabsCard title="Vertical Tab" variant="vertical"/>
 </main>}
function TabsCard({title,variant}:{title:string;variant:TabVariant}){return <section className={`tabs-card tabs-${variant}`}><header><h2>{title}</h2></header><div className="tabs-card-body"><InteractiveTabs variant={variant}/></div></section>}
function InteractiveTabs({variant}:{variant:TabVariant}){const [active,setActive]=useState<(typeof tabLabels)[number]>("Overview");const navigation=<nav className="premium-tabs" aria-label={`${variant} tabs`}>{tabLabels.map((label,index)=><button key={label} className={active===label?"active":""} onClick={()=>setActive(label)} aria-selected={active===label}>{variant==="icon"?tabIcons[index]:null}<span>{label}</span>{variant==="badge"&&tabBadges[label]?<small>{tabBadges[label]}</small>:null}</button>)}</nav>;return <div className={`tabs-demo ${variant}`}><div className="tabs-layout">{variant==="underline"?<div className="tabs-nav-frame">{navigation}</div>:navigation}<div className="tab-panel"><h3>{active}</h3><p>{active} ipsum dolor sit amet consectetur. Non vitae facilisis urna tortor placerat egestas donec. Faucibus diam gravida enim elit lacus a. Tincidunt fermentum condimentum quis et a et tempus. Tristique urna nisi nulla elit sit libero scelerisque ante.</p></div></div></div>}

function Generator({kind}:{kind:string}){
 const [text,setText]=useState("");const [answer,setAnswer]=useState("");const [historyOpen,setHistoryOpen]=useState(false);const [uploadedImage,setUploadedImage]=useState<string>("https://nextjs-demo.tailadmin.com/images/ai/img-1.png");
 const model=kind==="video"?"Google Veo 3.1":kind==="image"?"Nano Banana 2.0":"Claude Sonnet 4.6";
 const userPrompt=kind==="text"?"Can you generate some random, creative, and engaging placeholder text for me? It doesn't need to follow any specific structure—just something fun or interesting to fill space temporarily.":kind==="code"?"Create a responsive login form with Google and GitHub authentication.":"Minimalist building facade with vertical panels and greenery in a planter, set against a clear blue sky for a modern aesthetic.";
 const submit=()=>{if(text.trim()){setAnswer(text.trim());setText("")}};
 const uploadImage=(event:React.ChangeEvent<HTMLInputElement>)=>{const file=event.target.files?.[0];if(!file)return;const reader=new FileReader();reader.onload=()=>{if(typeof reader.result==="string")setUploadedImage(reader.result)};reader.readAsDataURL(file);event.target.value=""};
 return <div className={`generator-page generator-${kind}`}><main><nav><button className="generator-title">Generate responsive login <ChevronDown/></button><span/><button><Share2/>Share</button><button className="history-toggle" onClick={()=>setHistoryOpen(true)} aria-label="Open chat history"><MessageSquarePlus/></button></nav><section className="generator-conversation"><div className="generator-thread"><article className="user-bubble"><p>{answer||userPrompt}</p><footer><button aria-label="Edit"><Code2/></button><button aria-label="Copy"><MessageSquarePlus/></button></footer></article><article className="assistant-answer"><header><Sparkles/><span>{model}</span></header>{kind==="image"?<><p>I have generated a minimalist building facade with vertical panels and greenery in a planter, set against a clear blue sky for a modern aesthetic.</p><div className="generated-media generated-image"><img src={uploadedImage} alt="Generated minimalist building facade"/></div></>:kind==="video"?<><p>I have generated a minimalist building facade with vertical panels and greenery in a planter, set against a clear blue sky for a modern aesthetic.</p><div className="generated-media generated-video"><button aria-label="Play generated video"><Play/></button><span>Architectural concept video</span></div></>:kind==="code"?<><div className="generated-code"><header><span>HTML</span><button><MessageSquarePlus/>Copy code</button></header><pre>{`<!DOCTYPE html>\n<html lang="en">\n<head>\n  <meta charset="UTF-8" />\n  <title>Welcome Back</title>\n</head>\n<body>\n  <main class="login-container">\n    <h1>Welcome Back</h1>\n    <p>Please sign in to your account</p>\n    <form id="loginForm">\n      <input type="email" placeholder="Email" />\n      <input type="password" placeholder="Password" />\n      <button type="submit">Sign In</button>\n    </form>\n  </main>\n</body>\n</html>`}</pre></div><p>Here is the code for a login form with Google and GitHub authentication as described.</p></>:<><p>Lorem ipsum dolor sit amet, consectetur adipiscing elit. Vivamus et varius tortor. Aenean dui magna, vehicula in lacinia non, euismod sed odio. Aliquam erat volutpat.</p><div className="answer-actions"><button>Copy</button><button>Like</button><button>Dislike</button><button>Regenerate</button></div></>}</article></div><div className="prompt"><textarea aria-label="AI prompt" value={text} onChange={e=>setText(e.target.value)} onKeyDown={e=>{if(e.key==="Enter"&&!e.shiftKey){e.preventDefault();submit()}}} placeholder="Type your prompt here..."/><footer><span>{kind==="image"?<label className="image-upload" aria-label="Upload image"><input type="file" accept="image/*" onChange={uploadImage}/><Paperclip/></label>:<button><Plus/></button>}{kind!=="text"&&<><button><RectangleVertical/><span>3:4</span></button><button><Layers3/><span>1</span></button><button><Gem/><span>2K</span></button></>}{kind==="video"&&<><button>30s</button><button>Audio</button></>}<button>{kind==="video"?"Google Veo 3.1":kind==="image"?"Nano Banana Pro":"Claude Sonnet 4.6"}<ChevronDown/></button></span><button onClick={submit} aria-label="Send prompt">{kind==="image"?<Mic/>:<Send/>}</button></footer></div></section></main><aside className={historyOpen?"open":""}><button className="history-close" onClick={()=>setHistoryOpen(false)} aria-label="Close history"><X/></button><button className="new-chat"><Plus/>New Chat</button><label><Search/><input placeholder="Search..." aria-label="Search chat history"/></label><small>Today</small>{["Write a follow-up email to a client","Generate responsive login form layout","Create a warning state modal","Suggest color palette for dark theme"].map(x=><span key={x}>{x}</span>)}<small>Yesterday</small>{["Improve login page accessibility","Create a warning state modal with animation","Add password visibility toggle","Write validation logic for login form","Fix mobile responsiveness of login UI"].map(x=><span key={x}>{x}</span>)}<button className="show-more">Show more...<ChevronDown/></button></aside></div>
}

function AdvancedGenerator({kind}:{kind:"video"|"code"}){
 const [text,setText]=useState("");
 const [answer,setAnswer]=useState("");
 const [historyOpen,setHistoryOpen]=useState(false);
 const [videoSource,setVideoSource]=useState("");
 const isVideo=kind==="video";
 const model=isVideo?"Google Veo 3.1":"Claude Sonnet 4.6";
 const userPrompt=isVideo?"Minimalist building facade with vertical panels and greenery in a planter, set against a clear blue sky for a modern aesthetic.":"Create a login form in HTML with Google and GitHub authentication.";
 const submit=()=>{if(text.trim()){setAnswer(text.trim());setText("")}};
 const uploadVideo=(event:React.ChangeEvent<HTMLInputElement>)=>{const file=event.target.files?.[0];if(!file)return;setVideoSource(URL.createObjectURL(file));event.target.value=""};
 return <div className={`generator-page generator-${kind}`}>
  <main>
   <nav><button className="generator-title">Generate responsive login <ChevronDown/></button><span/><button><Share2/>Share</button><button className="history-toggle" onClick={()=>setHistoryOpen(true)} aria-label="Open chat history"><MessageSquarePlus/></button></nav>
   <section className="generator-conversation">
    <div className="generator-thread">
     <article className="user-bubble"><p>{answer||userPrompt}</p><footer><button aria-label="Edit"><Code2/></button><button aria-label="Copy"><MessageSquarePlus/></button></footer></article>
     <article className="assistant-answer">
      <header><Sparkles/><span>{model}</span></header>
      {isVideo?<><p>I have generated a minimalist building facade with vertical panels and greenery in a planter, set against a clear blue sky for a modern aesthetic.</p><div className="generated-media generated-video">{videoSource?<video src={videoSource} controls playsInline/>:<iframe src="https://www.youtube.com/embed/_iHmNaQBtKk?rel=0" title="Generated mountain landscape video" allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture" allowFullScreen/>}</div></>:<><p>Lorem ipsum dolor sit amet, consectetur adipiscing elit. Vivamus et varius tortor. Aenean dui magna, vehicula in lacinia non, euismod sed odio. Aliquam erat volutpat.</p><div className="generated-code"><header><span><Code2/>HTML</span><span><button aria-label="Copy code"><MessageSquarePlus/></button><button aria-label="Edit code"><Code2/></button></span></header><pre>{`<!DOCTYPE html>\n<html lang="en">\n<head>\n  <meta charset="UTF-8" />\n  <meta name="viewport" content="width=device-width, initial-scale=1.0" />\n  <title>Welcome Back</title>\n</head>\n<body>\n  <main class="login-container">\n    <h1>Welcome Back</h1>\n    <p>Please sign in to your account</p>\n    <form id="loginForm">\n      <input type="email" placeholder="Email" />\n      <input type="password" placeholder="Password" />\n      <button type="submit">Sign In</button>\n    </form>\n  </main>\n</body>\n</html>`}</pre></div></>}
     </article>
    </div>
    <div className="prompt"><textarea aria-label={`${isVideo?"Video":"Code"} prompt`} value={text} onChange={event=>setText(event.target.value)} onKeyDown={event=>{if(event.key==="Enter"&&!event.shiftKey){event.preventDefault();submit()}}} placeholder="Type your prompt here..."/><footer><span>{isVideo?<label className="media-upload" aria-label="Upload video"><input type="file" accept="video/*" onChange={uploadVideo}/><Paperclip/></label>:<button aria-label="Attach file"><Paperclip/></button>}{isVideo&&<><button><RectangleVertical/><span>3:4</span></button><button><Layers3/><span>1</span></button><button><Gem/><span>2K</span></button><button><span>30s</span></button><button><span>Audio</span></button></>}<button>{model}<ChevronDown/></button></span><button onClick={submit} aria-label="Send prompt"><Mic/></button></footer></div>
   </section>
  </main>
  <aside className={historyOpen?"open":""}><button className="history-close" onClick={()=>setHistoryOpen(false)} aria-label="Close history"><X/></button><button className="new-chat"><Plus/>New Chat</button><label><Search/><input placeholder="Search..." aria-label="Search chat history"/></label><small>Today</small>{["Write a follow-up email to a client","Generate responsive login form layout","Create a warning state modal","Suggest color palette for dark theme"].map(item=><span key={item}>{item}</span>)}<small>Yesterday</small>{["Improve login page accessibility","Create a warning state modal with animation","Add password visibility toggle","Write validation logic for login form","Fix mobile responsiveness of login UI"].map(item=><span key={item}>{item}</span>)}<button className="show-more">Show more...<ChevronDown/></button></aside>
 </div>
}

