function Layouts({n}:{title:string;n:number}){
 const [drawer,setDrawer]=useState(false);const [expanded,setExpanded]=useState(n!==6);const menus=layoutMenus[n as keyof typeof layoutMenus];const docs=n>=3&&n<=5;
 return <div className={`reference-layout layout-${n}`}><aside className={`${drawer?"open":""} ${expanded?"expanded":"collapsed"}`}><header><span className="mini-logo"><i/><i/><i/></span>{n!==6&&<b>{docs?"TailAdmin Docs":"TailAdmin"}{docs&&<small>v2.0.8-alpha</small>}</b>}<button onClick={()=>setExpanded(v=>!v)} aria-label="Toggle layout navigation"><ChevronDown/></button></header>{docs&&n!==5?<label><Search/><input placeholder="Search the docs"/></label>:null}<nav>{menus.map((item,i)=>{const heading=(n===2&&[0,11,16].includes(i))||(n===3&&[0,7].includes(i))||(n===5&&[0,9].includes(i));const accordion=n===4&&[0,7,8,9,10,11,12].includes(i);return heading?<h3 key={`${item}-${i}`}>{item}</h3>:<button key={`${item}-${i}`} className={(n===1&&i===0)||(n===3&&i===8)||(n===4&&i===2)||(n===5&&i===3)||(n===6&&i===0)?"active":""} title={item}>{n===6?<LayoutIcon index={i}/>:null}<span>{item}</span>{accordion?<ChevronDown/>:null}</button>})}</nav></aside><div className="layout-stage"><header><button onClick={()=>setDrawer(true)} aria-label="Open layout navigation"><Menu/></button><label><Search/><input placeholder="Search or type command..."/><kbd>⌘ K</kbd></label><span/><button className="theme-dot">◔</button>{docs?<button className="get-started">Get Started</button>:<><button><Bell/></button><button className="layout-user"><User/><b>Musharof</b><ChevronDown/></button></>}</header><main><div className="reference-kpis">{[1,2,3,4].map(x=><i key={x}/>)}</div><div className="reference-grid"><article/><article/></div>{n===5?<div className="reference-kpis bottom">{[1,2,3,4].map(x=><i key={x}/>)}</div>:null}</main></div>{drawer?<button className="layout-overlay" onClick={()=>setDrawer(false)} aria-label="Close layout navigation"/>:null}</div>
}
function LayoutIcon({index}:{index:number}){return <span className="layout-symbol">{["▦","□","◉","⬡","◇","✉","▣","♧","◔","⌘","◆"][index]}</span>}

function Charts({title,type}:{title:string;type:string}){if(type==="line")return <LineCharts title={title}/>;return <ChartCollection title={title} type={type}/>}
const lineChartData=[{month:"Jan",primary:180,secondary:40,single:22},{month:"Feb",primary:190,secondary:30,single:31},{month:"Mar",primary:170,secondary:50,single:28},{month:"Apr",primary:160,secondary:40,single:35},{month:"May",primary:175,secondary:55,single:32},{month:"Jun",primary:165,secondary:40,single:41},{month:"Jul",primary:170,secondary:70,single:38},{month:"Aug",primary:205,secondary:100,single:44},{month:"Sep",primary:230,secondary:110,single:40},{month:"Oct",primary:210,secondary:120,single:46},{month:"Nov",primary:240,secondary:150,single:43},{month:"Dec",primary:235,secondary:140,single:49}];
function LineCharts({title}:{title:string}){return <><Head title={title}/><div className="space-y-6">{[1,2,3].map(number=><section className="overflow-hidden rounded-2xl border border-[var(--border)] bg-[var(--panel)]" key={number}><header className="border-b border-[var(--border)] px-6 py-5"><h3 className="text-base font-medium">Line Chart {number}</h3></header><div className="h-[365px] px-5 pb-5 pt-10 sm:px-8">{number<3?<ResponsiveContainer width="100%" height="100%"><AreaChart data={lineChartData} margin={{top:8,right:10,left:-8,bottom:0}}><defs><linearGradient id={`line-primary-${number}`} x1="0" y1="0" x2="0" y2="1"><stop offset="0" stopColor="#465fff" stopOpacity=".28"/><stop offset="1" stopColor="#465fff" stopOpacity="0"/></linearGradient><linearGradient id={`line-secondary-${number}`} x1="0" y1="0" x2="0" y2="1"><stop offset="0" stopColor="#9cb7ef" stopOpacity=".24"/><stop offset="1" stopColor="#9cb7ef" stopOpacity="0"/></linearGradient></defs><CartesianGrid vertical={false} stroke="var(--border)"/><XAxis dataKey="month" axisLine={false} tickLine={false} tick={{fill:"var(--muted)",fontSize:12}} dy={10}/><YAxis domain={[0,250]} ticks={[0,50,100,150,200,250]} axisLine={false} tickLine={false} tick={{fill:"var(--muted)",fontSize:12}}/><Tooltip contentStyle={{background:"var(--panel)",border:"1px solid var(--border)",borderRadius:10}}/><Area animationDuration={1800} animationEasing="ease-in-out" type={number===1?"linear":"monotone"} dataKey="primary" stroke="#465fff" strokeWidth={2} fill={`url(#line-primary-${number})`} dot={false}/><Area animationDuration={1800} animationEasing="ease-in-out" type={number===1?"linear":"monotone"} dataKey="secondary" stroke="#9cb7ef" strokeWidth={2} fill={`url(#line-secondary-${number})`} dot={false}/></AreaChart></ResponsiveContainer>:<ResponsiveContainer width="100%" height="100%"><RechartsLineChart data={lineChartData} margin={{top:8,right:10,left:-8,bottom:0}}><CartesianGrid vertical={false} stroke="var(--border)"/><XAxis dataKey="month" axisLine={false} tickLine={false} tick={{fill:"var(--muted)",fontSize:12}} dy={10}/><YAxis domain={[0,50]} ticks={[0,10,20,30,40,50]} tickFormatter={value=>Number(value).toFixed(2)} axisLine={false} tickLine={false} tick={{fill:"var(--muted)",fontSize:12}}/><Tooltip contentStyle={{background:"var(--panel)",border:"1px solid var(--border)",borderRadius:10}}/><Line animationDuration={1800} animationEasing="ease-in-out" type="monotone" dataKey="single" stroke="#465fff" strokeWidth={2} dot={{r:4,fill:"#465fff",stroke:"#fff",strokeWidth:2}} activeDot={{r:6}}/></RechartsLineChart></ResponsiveContainer>}</div></section>)}</div></>}
function ChartCollection({title,type}:{title:string;type:string}){
 const count=type==="bar"?6:type==="pie"?5:type==="radar"?3:4;
 const charts=Array.from({length:count},(_,index)=><ChartPanel title={type==="bar"?(index===3?"Horizontal Bar Chart":`Bar Chart ${index+1}`):type==="pie"?`Donut Pie Chart ${index+1}`:type==="radar"?`Radar Chart ${index+1}`:index===0?"Radial Chart 1":index===1?"Radar Chart 2":index===2?"Radar Chart 3":"Radar Chart"} key={index}>{type==="bar"?<ReferenceBar variant={index}/>:type==="pie"?<ReferencePie variant={index}/>:type==="radar"?<ReferenceRadar variant={index}/>:<ReferenceRadial variant={index}/>}</ChartPanel>);
 return <><Head title={title}/>{type==="bar"?<div className="grid gap-6 lg:grid-cols-2">{charts.map((chart,index)=><div className={index<2?"lg:col-span-2":""} key={index}>{chart}</div>)}</div>:<div className="grid gap-6 lg:grid-cols-2">{charts}</div>}</>
}
function ChartPanel({title,children}:{title:string;children:React.ReactNode}){return <section className="overflow-hidden rounded-2xl border border-[var(--border)] bg-[var(--panel)]"><header className="border-b border-[var(--border)] px-6 py-5"><h3 className="text-base font-medium">{title}</h3></header>{children}</section>}
const barData=lineChartData.map((item,index)=>({...item,value:[160,380,190,290,175,185,285,100,205,385,275,100][index],direct:[40,55,48,50,38,42,52,33,45,58,54,41][index],referral:[24,28,26,30,22,25,28,19,26,31,29,23][index],organic:[15,17,16,14,18,16,17,13,16,18,17,15][index],social:[10,12,11,10,12,11,12,9,11,13,12,10][index]}));
function ReferenceBar({variant}:{variant:number}){
 const horizontal=variant===3;
 const stacked=variant===1;
 const chartData=variant===1?barData.slice(0,8):variant===4?barData.slice(0,5).map((item,index)=>({...item,direct:[78,58,68,38,64][index],referral:[88,48,63,23,0][index]})):barData;
 const series=stacked?[
  <Bar key="direct" animationDuration={1800} animationEasing="ease-in-out" name="Direct" dataKey="direct" stackId="sales" fill="#2f3bd3" radius={[0,0,8,8]} barSize={40}/>,
  <Bar key="referral" animationDuration={1800} animationEasing="ease-in-out" name="Referral" dataKey="referral" stackId="sales" fill="#465fff"/>,
  <Bar key="organic" animationDuration={1800} animationEasing="ease-in-out" name="Organic Search" dataKey="organic" stackId="sales" fill="#8098f9"/>,
  <Bar key="social" animationDuration={1800} animationEasing="ease-in-out" name="Social" dataKey="social" stackId="sales" fill="#c7d7fe" radius={[8,8,0,0]}/>
 ]:variant===2||variant===4?[
  <Bar key="direct" animationDuration={1800} animationEasing="ease-in-out" dataKey="direct" fill={variant===4?"#b7cdfc":"#465fff"} radius={[5,5,0,0]}/>,
  <Bar key="referral" animationDuration={1800} animationEasing="ease-in-out" dataKey="referral" fill={variant===4?"#465fff":"#b7cdfc"} radius={[5,5,0,0]}/>
 ]:[<Bar key="value" animationDuration={1800} animationEasing="ease-in-out" dataKey="value" fill="#465fff" radius={horizontal?[0,6,6,0]:[6,6,0,0]} barSize={horizontal?18:22}/>];
 const compact=variant>=2;
 const domain=variant===1?[0,120]:variant===4?[0,100]:[0,400];
 const ticks=variant===1?[0,20,40,60,80,100,120]:variant===4?[0,20,40,60,80,100]:[0,100,200,300,400];
 return <div className={`${compact?"h-[350px]":"h-[365px]"} flex flex-col px-5 pb-5 pt-8 sm:px-8`}>{variant===1?<div className="mb-4 flex flex-wrap items-center gap-x-6 gap-y-2 pl-3 text-sm text-[var(--muted)]">{[["Direct","#2f3bd3"],["Referral","#465fff"],["Organic Search","#8098f9"],["Social","#c7d7fe"]].map(([label,color])=><span className="inline-flex items-center gap-2" key={label}><i className="h-2.5 w-2.5 rounded-full" style={{backgroundColor:color}}/>{label}</span>)}</div>:null}<div className="min-h-0 flex-1"><ResponsiveContainer width="100%" height="100%"><RechartsBarChart data={chartData} layout={horizontal?"vertical":"horizontal"} margin={{top:8,right:12,left:horizontal?8:-6,bottom:0}}><CartesianGrid horizontal={!horizontal} vertical={horizontal} stroke="var(--border)"/><XAxis type={horizontal?"number":"category"} dataKey={horizontal?undefined:"month"} axisLine={false} tickLine={false} tick={{fill:"var(--muted)",fontSize:12}}/><YAxis type={horizontal?"category":"number"} dataKey={horizontal?"month":undefined} domain={horizontal?undefined:domain} ticks={horizontal?undefined:ticks} tickFormatter={variant===4?value=>`${value}%`:undefined} axisLine={false} tickLine={false} tick={{fill:"var(--muted)",fontSize:12}}/><Tooltip contentStyle={{background:"var(--panel)",border:"1px solid var(--border)",borderRadius:10}}/>{series}</RechartsBarChart></ResponsiveContainer></div></div>
}
const pieSets=[[{name:"Desktop",value:33,color:"#3641f5"},{name:"Mobile",value:47,color:"#6683f6"},{name:"Tablet",value:20,color:"#d6e3ff"}],[{name:"Downloads",value:28,color:"#8b75e8"},{name:"Apps",value:42,color:"#ff8138"},{name:"Documents",value:14,color:"#fdb022"},{name:"Media",value:16,color:"#32d583"}],[{name:"Chrome",value:45,color:"#465fff"},{name:"Safari",value:30,color:"#12b76a"},{name:"Firefox",value:25,color:"#f79009"}],[{name:"Completed",value:62,color:"#465fff"},{name:"Pending",value:24,color:"#9cb1ff"},{name:"Failed",value:14,color:"#f97066"}],[{name:"Direct",value:38,color:"#465fff"},{name:"Social",value:27,color:"#7f56d9"},{name:"Referral",value:21,color:"#06aed4"},{name:"Other",value:14,color:"#d0d5dd"}]];
function ReferencePie({variant}:{variant:number}){const data=pieSets[variant];return <div className="relative h-[375px] px-4 pb-5 pt-7"><ResponsiveContainer width="100%" height="100%"><PieChart><Pie animationDuration={1800} animationEasing="ease-in-out" data={data} dataKey="value" nameKey="name" cx="50%" cy="43%" innerRadius={variant===0?82:76} outerRadius={variant===0?120:108} paddingAngle={0} stroke="none">{data.map(item=><Cell fill={item.color} key={item.name}/>)}</Pie><Tooltip contentStyle={{background:"var(--panel)",border:"1px solid var(--border)",borderRadius:10}}/><Legend verticalAlign="bottom" iconType="circle" iconSize={9} wrapperStyle={{bottom:28}}/></PieChart></ResponsiveContainer>{variant===1?<div className="pointer-events-none absolute inset-x-0 top-[120px] text-center"><b className="block text-base">Total 135 GB</b><small className="mt-4 block">160</small></div>:null}</div>}
const radarCountries=[{label:"Estonia",a:9,b:4},{label:"Germany",a:8,b:6},{label:"France",a:4,b:7},{label:"Spain",a:6,b:8},{label:"Italy",a:4,b:5},{label:"Canada",a:5,b:6},{label:"Japan",a:7,b:4},{label:"Brazil",a:9,b:7}];const radarMonths=["January","February","March","April","May","June","July"].map((label,index)=>({label,a:[70,62,48,38,20,32,60][index],b:[55,42,51,78,28,46,49][index]}));
function ReferenceRadar({variant}:{variant:number}){const data=variant===1?radarMonths:radarCountries;return <div className="h-[445px] px-3 pb-5 pt-8"><ResponsiveContainer width="100%" height="100%"><RechartsRadarChart data={data} outerRadius="68%"><PolarGrid stroke="var(--border)"/><PolarAngleAxis dataKey="label" tick={{fill:"var(--muted)",fontSize:12}}/><PolarRadiusAxis angle={90} domain={[0,variant===1?90:10]} tick={{fill:"var(--muted)",fontSize:10}}/><Radar animationDuration={1800} animationEasing="ease-in-out" name="Desktop" dataKey="a" stroke="#465fff" fill="#465fff" fillOpacity={.25} strokeWidth={2}/>{variant>0?<Radar animationDuration={1800} animationEasing="ease-in-out" name="Mobile" dataKey="b" stroke="#ee46bc" fill="#ee46bc" fillOpacity={.18} strokeWidth={2}/>:null}<Tooltip contentStyle={{background:"var(--panel)",border:"1px solid var(--border)",borderRadius:10}}/>{variant===1?<Legend iconType="circle" iconSize={9}/>:null}</RechartsRadarChart></ResponsiveContainer></div>}
function ReferenceRadial({variant}:{variant:number}){const multi=variant>0;const data=multi?[{name:"Desktop",value:78,fill:"#4650a8"},{name:"Tablet",value:66,fill:"#ffb478"},{name:"Mobile",value:52,fill:"#b7a8f5"}]:[{name:"series-1",value:62.25,fill:"#5b72f2"}];return <div className="relative h-[354px] px-4 pb-5 pt-7"><ResponsiveContainer width="100%" height="100%"><RadialBarChart data={data} innerRadius={multi?"34%":"68%"} outerRadius={multi?"95%":"94%"} startAngle={multi?180:90} endAngle={multi?0:-270} barSize={multi?22:16}><RadialBar animationDuration={1800} animationEasing="ease-in-out" dataKey="value" background={{fill:"#f2f4f7"}} cornerRadius={variant===0?0:8}/><Tooltip contentStyle={{background:"var(--panel)",border:"1px solid var(--border)",borderRadius:10}}/></RadialBarChart></ResponsiveContainer>{variant===0?<div className="pointer-events-none absolute inset-0 grid place-items-center pt-10 text-center"><div><b className="block text-sm">series-1</b><strong className="mt-3 block text-xl">62.25%</strong></div></div>:null}</div>}

function Maps({vector}:{vector:boolean}){return <><Head title={vector?"Vector Map":"Maps"}/>{vector?<div className="vector-map-grid"><VectorMapCard title="Global User Distribution" subtitle="Track active users and customer locations worldwide" mode="points"/><VectorMapCard title="Country Traffic Analytics" subtitle="Visualize traffic volume and engagement by region" mode="traffic"/><VectorMapCard title="US Customer Heatmap" subtitle="Analyze customer density and regional performance" mode="usa"/></div>:<div className="map-grid"><MapCard title="Map View" subtitle="Clear view of locations at a glance"><Map city="New York"/></MapCard><MapCard title="Map 2" subtitle="Clear view of locations at a glance"><Map city="London"/></MapCard><MapCard title="Washington D.C. Region" subtitle="Interactive map with Home and Office Pinned" className="wide"><Map city="Washington D.C."/></MapCard></div>}</>}
function MapCard({title,subtitle,children,className=""}:{title:string;subtitle:string;children:React.ReactNode;className?:string}){return <section className={`map-reference-card ${className}`}><header><h2>{title}</h2><p>{subtitle}</p></header>{children}</section>}
function Map({city}:{city:string}){return <div className="catalog-map"><span><MapPin/>{city}</span><nav><button aria-label="Zoom in">+</button><button aria-label="Zoom out">−</button></nav></div>}
function VectorMapCard({title,subtitle,mode}:{title:string;subtitle:string;mode:string}){return <section className="vector-map-card"><header><h2>{title}</h2><p>{subtitle}</p></header><div className={`vector-world ${mode}`}><span/><i/><b/><em/><nav><button aria-label="Zoom in">+</button><button aria-label="Zoom out">−</button></nav></div></section>}

const sectionNames:Record<string,string[]>={alerts:["Success Alert","Warning Alert","Error Alert","Info Alert"],avatar:["Default Avatar","Avatar with online indicator","Avatar with Offline indicator","Avatar with busy indicator"],avatars:["Default Avatar","Avatar with online indicator","Avatar with Offline indicator","Avatar with busy indicator"],badge:["With Light Background","With Solid Background","Light Background with Left Icon","Solid Background with Left Icon","Light Background with Right Icon","Solid Background with Right Icon"],breadcrumb:["Default Breadcrumb","Breadcrumb With Icon","Breadcrumb With Icon","Breadcrumb With Icon"],buttons:["Primary Button","Primary Button with Left Icon","Primary Button with Right Icon","Secondary Button","Outline Button with Left Icon","Outline Button with Right Icon"],"buttons-group":["Primary Button Group","Primary Button Group with Left Icon","Primary Button Group with Right Icon","Secondary Button Group","Secondary Button Group with Left Icon","Secondary Button Group with Right Icon"],cards:["Card with Image","Horizontal Card with Image","Card with link","Card with Icon"],carousel:["Slides Only","With controls","With indicators","With controls and indicators"],dropdowns:["Default Dropdown","Dropdown With Divider","Dropdown With Icon","Dropdown With Icon and Divider"],images:["Responsive image","Image in 2 Grid","Image in 3 Grid"],links:["Colored Links","Colored CustomLinks with Underline","CustomLink Opacity","Link Opacity Hover"],list:["Unordered List","Ordered List","List With button","List With Icon","Horizontal List","List with checkbox","List with radio"],modals:["Default Modal","Vertically Centered Modal","Form In Modal","Full Screen Modal","Modal Based Alerts"],notification:["Announcement Bar","Toast Notification","Success Notification","Info Notification","Warning Notification","Error Notification"],notifications:["Announcement Bar","Toast Notification","Success Notification","Info Notification","Warning Notification","Error Notification"],pagination:["Pagination with Text","Pagination with Text and Icon","Pagination with  Icon"],popovers:["Default Popover","Popover With Button","Popover With Link"],"progress-bar":["Default Progress Bar","Progress Bar In Multiple Sizes","Progress Bar with Outside Label","Progress Bar with Inside Label"],ribbons:["Rounded Ribbon","Ribbon in Hover","Filled Ribbon","Ribbon in Hover"],spinners:["Spinner 1","Spinner 2","Spinner 3","Spinner 4"],tabs:["Default Tab","Tab With Underline","Tab with line and icon","Tab with badge","Vertical Tab"],tooltips:["Default Tooltip","White and Dark Tooltip","Tooltip Placement"],videos:["Video Ratio 16:9","Video Ratio 21:9","Video Ratio 4:3","Video Ratio 1:1"]};
function Elements({slug,title}:{slug:string;title:string}){const [active,setActive]=useState(1),[open,setOpen]=useState(false);return <><Head title={title}/><div className={`catalog-gallery ui ui-${slug}`}>{sectionNames[slug].map((name,i)=><Card title={name} key={`${name}-${i}`}><Element slug={slug} i={i} active={active} setActive={setActive} open={open} setOpen={setOpen}/></Card>)}</div>{open&&slug==="modals"&&<div className="catalog-modal" role="dialog" aria-modal="true" aria-label="Example modal" onMouseDown={()=>setOpen(false)}><div onMouseDown={e=>e.stopPropagation()}><button onClick={()=>setOpen(false)} aria-label="Close modal"><X/></button><CircleCheck/><h2>{active===3?"Add new contact":"Confirm your action"}</h2><p>{active===3?"Complete the form to add a new contact.":"Are you sure you want to continue?"}</p><footer><button onClick={()=>setOpen(false)}>Cancel</button><button className="catalog-primary" onClick={()=>setOpen(false)}>Confirm</button></footer></div></div>}</>}
function HomeMark(){return <span className="home-mark" aria-hidden="true">⌂</span>}
function SampleCard({variant}:{variant:number}){const linked=variant===2;return <article className={`sample-card c${variant}`}><div className={`card-photo photo-${variant%3}`}><ImageIcon/></div><section><h3>{variant===1?"": "Card title"}</h3><p>Lorem ipsum dolor sit amet, consectetur adipiscing elit. Animi architecto aspernatur cum et ipsum</p>{linked?<a href="#">⌁ Card link</a>:<button className="catalog-primary">Read more</button>}</section></article>}
function Element({slug,i,active,setActive,open,setOpen}:{slug:string;i:number;active:number;setActive:(n:number)=>void;open:boolean;setOpen:(x:boolean)=>void}){
 if(slug==="alerts")return <div className={`catalog-alert a${i}`}>{[<CircleCheck key="1"/>,<TriangleAlert key="2"/>,<AlertCircle key="3"/>,<Info key="4"/>][i]}<span><b>Important message</b><p>Please review the information shown here.</p></span><X/></div>;
 if(slug==="avatar"||slug==="avatars")return <div className={`avatar-row status-${i}`}>{[24,32,40,48,56,64].map(size=><i key={size} style={{width:size,height:size}}>{i>0?<b/>:null}</i>)}</div>;
 if(slug==="badge")return <div className="component-row">{["Primary","Success","Error","Warning","Info","Light","Dark"].map(x=><span className={`catalog-badge b${i} tone-${x.toLowerCase()}`} key={x}>{[2,3].includes(i)&&<Plus/>}{x}{i>3&&<Plus/>}</span>)}</div>;
 if(slug==="breadcrumb")return <div className={`breadcrumb-samples variant-${i}`}><div>{i===1?<HomeMark/>:null}<span>Home</span><ChevronRight/><b>UI Kits</b></div><div>{i===1?<HomeMark/>:null}<span>Home</span><ChevronRight/><span>UI Kits</span><ChevronRight/><b>Avatar</b></div></div>;
 if(slug==="buttons")return <div className="component-row"><button className={`catalog-primary ${i>2?"outline":""}`}>{i%3===1&&<Plus/>}Button Text{i%3===2&&<ArrowRight/>}</button><button className={`catalog-primary small ${i>2?"outline":""}`}>Button Text</button></div>;
 if(slug==="buttons-group")return <div className={`button-group group-${i}`}>{["Button Text","Button Text","Button Text"].map((x,j)=><button key={j}>{[1,4].includes(i)&&<Code2/>}{x}{[2,5].includes(i)&&<Code2/>}</button>)}</div>;
 if(slug==="cards")return i===0?<div className="cards-row">{[0,1,2].map(card=><SampleCard key={card} variant={card}/>)}</div>:<SampleCard variant={i+2}/>;
 if(slug==="carousel")return <div className={`catalog-carousel carousel-${i}`}><span>Beautiful workspace</span>{i>0&&<><button aria-label="Previous slide"><ArrowLeft/></button><button aria-label="Next slide"><ArrowRight/></button></>}{i>1?<nav aria-label="Slide selection"><i/><i className="active"/><i/></nav>:null}</div>;
 if(slug==="dropdowns")return <div className={`dropdown dropdown-${i}`}><button onClick={()=>setOpen(!open)} aria-expanded={open}>Options <ChevronDown/></button>{open&&<nav>{["Edit account","Settings","Support","Sign out"].map((x,j)=><button className={j===3&&i%2===1?"divided":""} key={x}>{i>1?<Check/>:null}{x}</button>)}</nav>}</div>;
 if(slug==="images")return <div className={`image-samples cols${i+1}`}>{Array.from({length:i+1},(_,j)=><i className={`sample-image image-${j}`} role="img" aria-label={`Workspace sample ${j+1}`} key={j}/>)}</div>;
 if(slug==="links")return <div className={`link-samples l${i}`}>{["Primary link","Secondary link","Success link","Error link","Warning link","Info link"].map(x=><a href={`#${x.toLowerCase().replaceAll(" ","-")}`} key={x}>{x}</a>)}</div>;
 if(slug==="list")return <ul className={`catalog-list l${i}`}>{["Dashboard overview","Account settings","Notifications","Billing details"].map((x,j)=><li key={x}>{i===3?<Check/>:null}{i===5?<input aria-label={x} type="checkbox" defaultChecked={!j}/>:null}{i===6?<input aria-label={x} name="catalog-radio" type="radio" defaultChecked={!j}/>:null}<span>{x}</span>{i===2?<button aria-label={`Open ${x}`}><ChevronRight/></button>:null}</li>)}</ul>;
 if(slug==="modals")return <button className="catalog-primary" onClick={()=>{setActive(i);setOpen(true)}}>Open Modal</button>;
 if(slug==="notification"||slug==="notifications")return <div className={`catalog-notification notice-${i}`}>{i===0?<Bell/>:i===1?<span className="notice-avatar">AR</span>:i===2?<CircleCheck/>:i===3?<Info/>:i===4?<TriangleAlert/>:<AlertCircle/>}<span><b>{i===0?"Announcement":i===1?"New message":i===2?"Success":i===3?"Information":i===4?"Warning":"Something went wrong"}</b><p>{i<2?"You have a new update waiting.":"Your latest action has been processed."}</p></span><button aria-label="Dismiss notification"><X/></button></div>;
 if(slug==="pagination")return <div className={`pagination pagination-${i}`}><button aria-label="Previous page"><ArrowLeft/>{i<2?<span>Previous</span>:null}</button>{[1,2,3,4,5].map(x=><button aria-label={`Page ${x}`} className={active===x?"active":""} onClick={()=>setActive(x)} key={x}>{x}</button>)}<button aria-label="Next page">{i<2?<span>Next</span>:null}<ArrowRight/></button></div>;
 if(slug==="popovers")return <div className="popover"><button className="catalog-primary" onClick={()=>setOpen(!open)}>Click me</button>{open&&<span><b>Popover title</b><p>Useful supporting information.</p></span>}</div>;
 if(slug==="progress-bar")return <div className="progresses">{[25,50,75,90].map(x=><div key={x}><span>{i>1&&`${x}%`}</span><i><b style={{width:`${x}%`}}>{i===3&&`${x}%`}</b></i></div>)}</div>;
 if(slug==="ribbons")return <div className={`ribbon r${i}`}><span>Featured</span><h3>New product</h3><p>Highlight important content with a clean ribbon label.</p></div>;
 if(slug==="spinners")return <div className={`spinner-row spinner-${i}`}>{[1,2,3,4].map(x=><i style={{animationDelay:`${x*80}ms`}} key={x}/>)}</div>;
 if(slug==="tabs")return <div className={`tab-example tab-${i}`}><div className={`tabs t${i}`}>{["Overview","Notification","Analytics","Customers"].map((x,j)=><button className={active===j?"active":""} onClick={()=>setActive(j)} key={x}>{i===2?<Info/>:null}{x}{i===3&&j===1?<b>8</b>:null}</button>)}</div><article className="tab-content"><h3>{["Overview","Notification","Analytics","Customers"][active]}</h3><p>Explore the selected dashboard information and recent activity.</p></article></div>;
 if(slug==="tooltips")return <div className={`tooltip-row tooltip-set-${i}`}>{["Top","Right","Bottom","Left"].map((position,j)=><div className={`tooltip t${j}`} key={position}><button className="catalog-primary">{position}</button><span>{i===1&&j%2?"Dark":"Helpful"} tooltip</span></div>)}</div>;
 return <div className={`video-sample v${i}`}><button aria-label="Play video"><Play/></button><span>Video preview</span></div>;
}
